ARTIFACT_VERSION = "v0_2"
DICTIONARY_COLUMNS = [
    "column_name", "business_name", "description", "data_type", "role",
    "allowed_values", "sentinel_value", "sentinel_meaning", "source_system", "notes",
]


def _case(context: str, index: int, name: str, description: str, data_type: str, role: str,
          decision: str, primary: str = "", secondary: str = "", category: str = "description") -> dict[str, str]:
    return {
        "case_id": f"{context.lower()}_{index:02d}", "suggested_context": context,
        "column_name": name, "description": description, "data_type": data_type, "role": role,
        "expected_decision": decision, "expected_primary_role": primary,
        "expected_secondary_roles": secondary, "case_category": category,
        "ground_truth_rationale": description or "The supplied metadata is intentionally insufficient.",
    }


