def _dictionary(rows: list[tuple[str, str, str, str, str, str, str, str, str, str]]) -> pd.DataFrame:
    return pd.DataFrame(rows, columns=DICTIONARY_COLUMNS)


def _write_fixture(output: Path, name: str, data: pd.DataFrame, dictionary: pd.DataFrame,
                   declarations: dict[str, Any], bindings: dict[str, list[str]], tags: list[dict[str, str]]) -> None:
    data.to_csv(output / f"{name}_data_{ARTIFACT_VERSION}.csv", index=False)
    dictionary.to_csv(output / f"{name}_dictionary_{ARTIFACT_VERSION}.csv", index=False)
    (output / f"{name}_dictionary_{ARTIFACT_VERSION}.yaml").write_text(
        yaml.safe_dump({"columns": dictionary.fillna("").to_dict(orient="records")}, sort_keys=False), encoding="utf-8"
    )
    (output / f"{name}_runtime_declarations_{ARTIFACT_VERSION}.yaml").write_text(yaml.safe_dump(declarations, sort_keys=False), encoding="utf-8")
    (output / f"{name}_expected_role_bindings_{ARTIFACT_VERSION}.yaml").write_text(yaml.safe_dump({"bindings": bindings}, sort_keys=False), encoding="utf-8")
    pd.DataFrame(tags, columns=["row_id", "column_name", "expected_tag", "reason_code"]).to_csv(
        output / f"{name}_expected_cell_tags_{ARTIFACT_VERSION}.csv", index=False
    )


