        ("RATE_TYPE", "Rate type", "Fixed or floating benchmark-linked pricing basis", "string", "feature", "FIXED|FLOATING", "", "", "TEST_PD", ""),
        ("BRR", "Borrower risk rating", "Internal borrower risk rating currently in force", "string", "score", "G1-G8", "", "", "TEST_PD", ""),
        ("NOI", "Net operating income", "Periodic net operating income", "float", "feature", "", "-999", "source unavailable", "TEST_PD", ""),
