        row_id = f"LGD{case:04d}"; open_case = case % 5 == 0; cured = case % 11 == 0
        status = "OPEN" if open_case else "FINISHED"; trigger = "JUDGEMENT" if case % 7 == 0 else "ARREARS"
        rows.append({"ROW_ID": row_id, "CASE_ID": f"C{case:05d}", "AS_OF_DT": "2024-12-31", "REC_SEG": ["CRE","SME","MORTGAGE"][case%3], "WO_STATUS": status, "LGD_REAL": "" if open_case else round(0.15+(case%50)/100,2), "NET_REC_AMT": "" if open_case else 5000+case*20, "TTR_MTH": "" if open_case else case%36+1, "CURE_IND": int(cured), "DISP_PROCEEDS": "" if cured or open_case else 15000+case*30, "SALE_DT": "" if cured or open_case else "2024-06-30", "DPD_AT_DFLT": "" if trigger=="JUDGEMENT" else 90+case%60, "DOD_BASIS": trigger, "DOD_REG_VER": f"V{case%3+1}" if trigger=="JUDGEMENT" else "", "ORIG_BAL": 100000+case*100})
