        ("WO_STATUS","Workout status","Whether workout is open or finished","string","target","OPEN|FINISHED","","","TEST_LGD",""), ("LGD_REAL","Realised LGD","Final realised loss given default","float","target","","","","TEST_LGD",""),
        ("NET_REC_AMT","Net recovery","Final net recovery amount","float","target","","","","TEST_LGD",""), ("TTR_MTH","Time to resolution","Months from default to resolution","integer","target","","","","TEST_LGD",""),
        ("CURE_IND","Cure indicator","Return to performing without realisation","integer","target","0|1","","","TEST_LGD",""), ("DISP_PROCEEDS","Disposal proceeds","Proceeds from collateral sale","float","target","","","","TEST_LGD",""),
        ("SALE_DT","Sale date","Date collateral was realised","date","date","","","","TEST_LGD",""), ("DPD_AT_DFLT","DPD at default","Days past due at default","integer","feature","","","","TEST_LGD",""),
        ("DOD_BASIS","Default basis","Arrears or judgement definition-of-default basis","string","feature","ARREARS|JUDGEMENT","","","TEST_LGD",""), ("DOD_REG_VER","Default regime","Policy version for judgement-based default","string","feature","","","","TEST_LGD",""),
        ("ORIG_BAL","Original balance","Balance fixed at origination","float","feature","","","","TEST_LGD",""),
