def _ead_fixture(output: Path) -> None:
    rows, tags = [], []
    for facility in range(1, 101):
        revolving = facility % 4 != 0; default_month = facility % 13 if facility % 6 == 0 else None
        for month in range(1, 13):
            row_id=f"EAD{facility:03d}_{month:02d}"; event = int(default_month == month)
            limit = 100000 + facility*500 if revolving else ""; activity = 500 if facility%25==0 and 4<=month<=6 else (facility+month)%5*100
            drawn = 50000 + facility*100 + month*200
            if facility%25==0 and 4<=month<=6: drawn = 60000 + facility*100
            undrawn = max(0, float(limit)-drawn) if revolving else ""; available = undrawn if revolving else ""
            observed = default_month is not None and month >= default_month
            ead = drawn + (0.5*undrawn if revolving else 0) if observed else ""
            future = 0.5*undrawn if observed and revolving else ""; ccf = 0.5 if observed and revolving else ""
            rows.append({"ROW_ID":row_id,"FAC_ID":f"E{facility:04d}","OBS_MTH":f"2024-{month:02d}","EAD_SEG":["CARDS","SME","CORP","TERM"][facility%4],"DFLT_EVT":event,"DFLT_DT":f"2024-{month:02d}-15" if event else "","OS_BAL":drawn,"UNDRAWN_AMT":undrawn,"FAC_LMT":limit,"AVAIL_CR":available,"EAD_AMT":ead,"FUT_DRAW":future,"CCF":ccf,"COMMIT_ST":"COMMITTED" if revolving else "NO_COMMITMENT","FAC_TYPE":"REVOLVING" if revolving else "TERM","DRAW_AMT":activity,"UTIL_PCT":round(drawn/float(limit),4) if revolving else ""})
            if not observed:
                tags.append({"row_id":row_id,"column_name":"EAD_AMT","expected_tag":"CENSORED","reason_code":"ead_measurement_not_observed"})
            if not revolving:
                for column in ("UNDRAWN_AMT","FAC_LMT","AVAIL_CR","FUT_DRAW","CCF"):
                    tags.append({"row_id":row_id,"column_name":column,"expected_tag":"NOT_APPLICABLE","reason_code":"no_commitment_concept"})
            elif not observed:
                for column in ("FUT_DRAW","CCF"):
                    tags.append({"row_id":row_id,"column_name":column,"expected_tag":"CENSORED","reason_code":"ead_measurement_not_observed"})
            if facility%25==0 and 4<=month<=6:
                tags.append({"row_id":row_id,"column_name":"OS_BAL","expected_tag":"STALE_FROZEN","reason_code":"activity_without_balance_change"})
    columns = [
        ("ROW_ID","Row identifier","Synthetic technical row reference; not a business entity key","string","ignore","","","","TEST_EAD",""),("FAC_ID","Facility identifier","Unique facility identifier","string","identifier","","","","TEST_EAD",""),
        ("OBS_MTH","Observation month","Ordered monthly observation period","string","period","","","","TEST_EAD",""),("EAD_SEG","EAD segment","Exposure-at-default portfolio segment","string","group","CARDS|SME|CORP|TERM","","","TEST_EAD",""),
        ("DFLT_EVT","Default event","Occurrence of EAD measurement default event","integer","target","0|1","","","TEST_EAD",""),("DFLT_DT","Default date","Date default occurred","date","date","","","","TEST_EAD",""),
        ("OS_BAL","Outstanding balance","Current drawn and outstanding amount","float","feature","","","","TEST_EAD",""),("UNDRAWN_AMT","Undrawn amount","Committed amount not yet drawn","float","feature","","","","TEST_EAD",""),
        ("FAC_LMT","Facility limit","Current contractual facility limit","float","feature","","","","TEST_EAD",""),("AVAIL_CR","Available credit","Amount currently available to draw","float","feature","","","","TEST_EAD",""),
        ("EAD_AMT","Exposure at default","Realised exposure measured at default date","float","target","","","","TEST_EAD",""),("FUT_DRAW","Future drawdown","Additional amount drawn between observation and default","float","target","","","","TEST_EAD",""),
        ("CCF","Credit conversion factor","Realised conversion factor at default","float","target","","","","TEST_EAD",""),("COMMIT_ST","Commitment status","Committed or no-commitment status","string","feature","COMMITTED|NO_COMMITMENT","","","TEST_EAD",""),
        ("FAC_TYPE","Facility type","Revolving or term facility structure","string","feature","REVOLVING|TERM","","","TEST_EAD",""),("DRAW_AMT","Draw amount","Drawing activity during the month","float","feature","","","","TEST_EAD",""),
        ("UTIL_PCT","Utilisation","Share of facility limit currently drawn","float","feature","","","","TEST_EAD",""),
    ]
    declarations={"as_of_date":"2024-12-31","ead_target_observation_policy":"realised targets observed only at default measurement point","ead_measurement_point_by_target":{"EAD_AMT":"default date","FUT_DRAW":"default date","CCF":"default date"},"default_event_domain":{"1":"default occurred"},"commitment_applicability_by_facility_type":{"REVOLVING":"applicable","TERM":"not applicable"},"behavioural_balance_update_frequency":"monthly","field_specific_sentinel_definitions":{},"variance_window":3,"minimum_row_count":3,"not_applicable_share_threshold":0.8}
    bindings={"FAC_ID":["entity_id"],"OBS_MTH":["period"],"EAD_SEG":["segment"],"DFLT_EVT":["default_event"],"DFLT_DT":["default_date"],"OS_BAL":["drawn_balance"],"UNDRAWN_AMT":["undrawn_commitment"],"FAC_LMT":["credit_limit"],"AVAIL_CR":["available_commitment"],"EAD_AMT":["exposure_at_default"],"FUT_DRAW":["future_drawdown"],"CCF":["conversion_factor"],"COMMIT_ST":["commitment_status"],"FAC_TYPE":["facility_type"],"DRAW_AMT":["exposure_change_indicators"],"UTIL_PCT":["utilisation_measure"]}
    _write_fixture(output, "ead", pd.DataFrame(rows), _dictionary(columns), declarations, bindings, tags)


def generate_all(output: Path = DEFAULT_OUTPUT) -> dict[str, int]:
    output.mkdir(parents=True, exist_ok=True)
    benchmark = pd.DataFrame(benchmark_cases())
    benchmark.to_csv(output / f"role_matching_benchmark_{ARTIFACT_VERSION}.csv", index=False)
    _pd_fixture(output); _lgd_fixture(output); _ead_fixture(output)
    manifest = {"benchmark_cases": len(benchmark), "pd_rows": 1200, "lgd_rows": 400, "ead_rows": 1200, "seed_policy": "deterministic formulas; no random state"}
    (output / f"fixture_manifest_{ARTIFACT_VERSION}.json").write_text(json.dumps(manifest, indent=2), encoding="utf-8")
    return {key: value for key, value in manifest.items() if isinstance(value, int)}


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    args = parser.parse_args()
    print(generate_all(args.output))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
